let homeVerses=[],homeVersePrefs=[],homeVerseReady=false,routinePin='',routineData=null,routinePerson='mine',routineMonth='',routineDay=0,routineBusy=false,goalVisible=false,routineOverview=false,routineTab='daily';
const peopleLabels={mine:'민수',bora:'보라'};
const dailyItems=[['prayer','기도'],['daily_text','일용할 성구'],['bible','성경 읽기'],['ministry','야외 봉사'],['new_content','새로운 내용'],['detox','디지털 디톡스']];
const weeklyItems=[['personal','개인 연구'],['family','가족 숭배'],['meeting','평일 집회 예습'],['watchtower','파수대 연구 예습'],['custom1',''],['custom2','']];
const monthlyItems=[['broadcast','JW 월간 방송'],['report','야외 봉사 보고'],['custom1',''],['custom2','']];
const topicSets=[['여호와와의 관계',['기도','믿음','성경 읽기','감사']],['부부와 가족',['사랑','의사소통','용서','존중']],['일상과 마음',['불안','인내','친절','희망']]];
function relatedTopics(name){const set=topicSets.find(([,items])=>items.includes(name));if(!set)return '';const list=set[1].filter(x=>x!==name);return `<div class="related-topics"><span>함께 볼 주제</span>${list.map(t=>`<a href="${idHash('@topic:'+t)}">${esc(t)}</a>`).join('')}</div>`}
function suggestedTopics(){return `<div class="topic-suggestions">${topicSets.map(([label,topics])=>`<section><h2>${esc(label)}</h2><div>${topics.map(t=>`<a href="${idHash('@topic:'+t)}">${esc(t)}</a>`).join('')}</div></section>`).join('')}</div>`}
function familyView(){const sessions=new Map();for(const n of notes){if(!n.person.startsWith('@family:'))continue;const name=n.person.slice(8);if(!sessions.has(name))sessions.set(name,[]);sessions.get(name).push(n)}const list=[...sessions].sort((a,b)=>String(b[1][0].created_at).localeCompare(String(a[1][0].created_at)));$('#app').innerHTML=`<a class="back section-back" href="#/home">← 처음</a><div class="workspace explore-workspace"><div class="section-row"><h1 class="people-title">가족 숭배</h1><button class="secondary" id="new-family">+ 추가</button></div>${list.length?list.map(([name,ns])=>`<section class="explore-group"><h2><a href="${idHash('@family:'+name)}">${esc(name)}</a></h2>${ns.map(n=>`<a class="explore-note" href="${idHash(n.person)}?note=${encodeURIComponent(n.id)}"><span><b>${esc(n.title)}</b><small>${n.author==='mine'?'민수':'보라'} · ${esc(date(n.created_at))}</small></span><span>→</span></a>`).join('')}</section>`).join(''):'<div class="empty">기록 없음</div>'}</div>`;const open=()=>{newContextKind='family';$('#context-title').textContent='가족 숭배';$('#context-label').textContent='날짜 또는 주제';$('#context-name').placeholder='예: 11월 첫째 주';$('#context-name').value='';$('#context-dialog').showModal()};$('#new-family').onclick=open;$('#first-family')?.addEventListener('click',open)}
async function loadHomeVerses(){try{const [a,b]=await Promise.all([fetch(BASE+'/rest/v1/study_verse_collection?select=id,person,reference,verse_text,created_at&order=created_at.asc',{headers}),fetch(BASE+'/rest/v1/study_verse_preferences?select=person,mode,selected_id',{headers})]);if(!a.ok||!b.ok){homeVerseReady=false;homeVerses=[];homeVersePrefs=[];return}homeVerseReady=true;homeVerses=await a.json();homeVersePrefs=await b.json()}catch{homeVerseReady=false;homeVerses=[];homeVersePrefs=[]}}
function selectedHomeVerse(person){const list=homeVerses.filter(v=>v.person===person);if(!list.length)return null;const pref=homeVersePrefs.find(x=>x.person===person);if(pref?.mode==='auto'){const d=new Date(),day=Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/86400000);return list[((day%list.length)+list.length)%list.length]}return list.find(v=>v.id===pref?.selected_id)||list[0]}
function renderHomeVerses(){const box=$('#home-verses');if(!box)return;box.innerHTML=['mine','bora'].map(person=>{const v=selectedHomeVerse(person);return `<article class="home-verse ${v?'has-verse':'is-empty'}"><div class="home-verse-head"><span>${peopleLabels[person]}</span><button class="verse-edit" data-verse-person="${person}" aria-label="${peopleLabels[person]} 성구 관리">${v?'성구 관리':'+ 성구'}</button></div>${v?.verse_text?`<p class="verse-calligraphy">${esc(v.verse_text)}</p>`:''}${v?.reference?`<a class="verse-reference" href="${esc(verseUrl(v.reference))}" target="_blank" rel="noopener noreferrer">${esc(v.reference)} ↗</a>`:''}</article>`}).join('');box.querySelectorAll('[data-verse-person]').forEach(b=>b.onclick=()=>openHomeVerse(b.dataset.versePerson))}
function renderSavedVerses(){const person=$('#home-verse-person').value,pref=homeVersePrefs.find(x=>x.person===person),list=homeVerses.filter(x=>x.person===person),selected=selectedHomeVerse(person);$('#home-verse-mode').value=pref?.mode||'manual';$('#home-verse-list').innerHTML=list.map(v=>`<article class="saved-verse"><p>${esc(v.verse_text)}</p>${v.reference?`<small>${esc(v.reference)}</small>`:''}<div><button type="button" data-verse-choose="${esc(v.id)}" class="link">${pref?.mode!=='auto'&&selected?.id===v.id?'선택됨':'선택'}</button><button type="button" data-verse-update="${esc(v.id)}" class="link">수정</button><button type="button" data-verse-delete="${esc(v.id)}" class="link">삭제</button></div></article>`).join('');document.querySelectorAll('[data-verse-choose]').forEach(b=>b.onclick=()=>changeVerse('choose',{id:b.dataset.verseChoose}));document.querySelectorAll('[data-verse-update]').forEach(b=>b.onclick=()=>{const v=list.find(x=>x.id===b.dataset.verseUpdate);if(!v)return;$('#home-verse-id').value=v.id;$('#home-verse-reference').value=v.reference;$('#home-verse-text').value=v.verse_text;$('#home-verse-save').textContent='수정 저장';$('#home-verse-cancel').hidden=false;$('#home-verse-text').focus()});document.querySelectorAll('[data-verse-delete]').forEach(b=>b.onclick=()=>{if(confirm('이 성구를 지울까요?'))changeVerse('delete',{id:b.dataset.verseDelete})})}
function openHomeVerse(person){$('#home-verse-person').value=person;$('#home-verse-title').textContent=peopleLabels[person]+' 성구';$('#home-verse-id').value='';$('#home-verse-reference').value='';$('#home-verse-text').value='';$('#home-verse-password').value='';$('#home-verse-save').textContent='+ 성구 저장';$('#home-verse-cancel').hidden=true;$('#home-verse-message').textContent=homeVerseReady?'':'저장 공간 연결이 아직 필요합니다.';renderSavedVerses();$('#home-verse-dialog').showModal()}
async function changeVerse(action,data){if(!homeVerseReady){$('#home-verse-message').textContent='저장 공간 연결이 아직 필요합니다.';return false}const password=$('#home-verse-password').value;if(!password){$('#home-verse-message').textContent='비밀번호를 입력해 주세요.';$('#home-verse-password').focus();return false}try{const result=await rpc('study_verse_change',{p_password:password,p_person:$('#home-verse-person').value,p_action:action,p_data:data});if(!result?.ok)throw Error(result?.error||'저장하지 못했습니다.');await loadHomeVerses();renderSavedVerses();renderHomeVerses();$('#home-verse-message').textContent='저장했습니다.';return true}catch(err){$('#home-verse-message').textContent=err.message;renderSavedVerses();return false}}
async function setHomeVerse(e){e.preventDefault();const btn=$('#home-verse-save'),id=$('#home-verse-id').value;btn.disabled=true;try{const ok=await changeVerse(id?'update':'create',{id:id||null,reference:$('#home-verse-reference').value.trim(),verse_text:$('#home-verse-text').value.trim()});if(ok){$('#home-verse-id').value='';$('#home-verse-reference').value='';$('#home-verse-text').value='';btn.textContent='+ 성구 저장';$('#home-verse-cancel').hidden=true}}finally{btn.disabled=false}}
function todayLocal(){const d=new Date();return {month:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,day:d.getDate()}}
function shiftMonth(month,n){const [y,m]=month.split('-').map(Number),d=new Date(y,m-1+n,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function monthDays(month){const [y,m]=month.split('-').map(Number);return new Date(y,m,0).getDate()}
function currentSettings(){return routineData?.settings.find(x=>x.person===routinePerson)||{goal:null,monthly_1:'',monthly_2:'',weekly_1:'',weekly_2:'',month_verse:''}}
function checked(freq,item,pos){return routineData?.checks.some(x=>x.person===routinePerson&&x.frequency===freq&&x.item===item&&x.position===pos)||false}
function countScore(){return (routineData?.checks||[]).filter(x=>x.person===routinePerson).reduce((sum,x)=>sum+(x.frequency==='daily'&&x.item==='detox'?2:1),0)}
async function readRoutine(){const r=await rpc('study_routine_read',{p_password:routinePin,p_month:routineMonth});if(!r?.ok)throw Error(r?.error||'불러오지 못했습니다.');routineData=r}
async function writeRoutine(action,data){const r=await rpc('study_routine_write',{p_password:routinePin,p_person:routinePerson,p_month:routineMonth,p_action:action,p_data:data});if(!r?.ok)throw Error(r?.error||'저장하지 못했습니다.')}
function routineView(){if(!routineMonth){let t=todayLocal();routineMonth=t.month;routineDay=t.day}if(!routinePin){$('#app').innerHTML=`<a class="back section-back" href="#/home">← 처음</a><div class="workspace routine-unlock"><h1 class="people-title">영적 일과</h1><form id="routine-unlock"><label>비밀번호<input id="routine-password" type="password" autocomplete="current-password" required></label><p id="routine-error" class="small" role="status"></p><button class="primary">열기</button></form></div>`;$('#routine-unlock').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;routinePin=$('#routine-password').value;try{await readRoutine();routineRender()}catch(err){routinePin='';$('#routine-error').textContent=err.message}finally{btn.disabled=false}};return}if(!routineData){$('#app').innerHTML='<div class="notice">불러오는 중…</div>';readRoutine().then(routineRender).catch(err=>{routinePin='';routineView();$('#routine-error').textContent=err.message});return}routineRender()}
function routineRender(){const s=currentSettings(),today=todayLocal();routineDay=Math.min(Math.max(routineDay||1,1),monthDays(routineMonth));const days=Array.from({length:monthDays(routineMonth)},(_,i)=>i+1);const goal=s.goal===null||s.goal===undefined?'목표 +':goalVisible?`목표 ${s.goal}`:'목표 •••';const boxes=(freq,item,positions)=>positions.map(pos=>`<button class="routine-check ${checked(freq,item,pos)?'checked':''}" data-freq="${freq}" data-item="${item}" data-pos="${pos}" aria-pressed="${checked(freq,item,pos)}" aria-label="${esc(itemLabel(freq,item))} ${freq==='daily'?pos+'일':freq==='weekly'?pos+'주':'이번 달'} ${checked(freq,item,pos)?'완료':'미완료'}">${freq==='weekly'?pos:(checked(freq,item,pos)?'✓':'')}</button>`).join('');const customLabel=(freq,item)=>{const field=(freq==='weekly'?'weekly_':'monthly_')+(item==='custom1'?'1':'2');return s[field]?`<button class="custom-label" data-setting="${field}">${esc(s[field])}</button>`:`<button class="custom-label muted" data-setting="${field}">+ 항목</button>`};$('#app').innerHTML=`<a class="back section-back" href="#/home">← 처음</a><div class="workspace routine"><div class="routine-head"><h1 class="people-title">영적 일과</h1><div class="filters" aria-label="작성자">${['mine','bora'].map(p=>`<button data-routine-person="${p}" aria-pressed="${p===routinePerson}" class="${p===routinePerson?'active':''}">${peopleLabels[p]}</button>`).join('')}</div></div><div class="routine-month"><button class="month-arrow" id="month-prev" aria-label="이전 달">‹</button><label class="month-picker"><span aria-hidden="true">${Number(routineMonth.slice(0,4))}년 ${Number(routineMonth.slice(5))}월</span><span class="sr-only">연도와 월</span><input type="month" id="routine-month" value="${routineMonth}" aria-label="연도와 월"></label><button class="month-arrow" id="month-next" aria-label="다음 달">›</button></div><div class="routine-summary"><strong>점수 ${countScore()}</strong><button class="goal-button" id="routine-goal">${goal}</button>${goalVisible&&s.goal!==null&&s.goal!==undefined?'<button class="link" id="goal-edit">수정</button>':''}</div><div class="routine-tabs" role="group" aria-label="일과 선택">${[['daily','일간'],['weekly','주간'],['monthly','월간']].map(([id,label])=>`<button type="button" data-routine-tab="${id}" aria-pressed="${routineTab===id}" class="${routineTab===id?'active':''}">${label}</button>`).join('')}</div><div class="routine-section ${routineTab==='daily'?'routine-active':''}" data-routine-section="daily"><div class="routine-section-head"><h2>매일 <span class="daily-count">${dailyItems.filter(([id])=>checked('daily',id,routineDay)).length}/6</span></h2><button class="link" id="routine-view-toggle">${routineOverview?'하루 보기':'한 달 보기'}</button></div>${routineOverview?`<div class="routine-calendar" aria-label="날짜별 완료 현황">${days.map(d=>{const count=dailyItems.filter(([id])=>checked('daily',id,d)).length;return `<button data-calendar-day="${d}" class="calendar-day intensity-${count} ${d===routineDay?'active':''}" aria-label="${d}일 ${count===6?'6개 모두 완료':count+'개 완료'}"><strong>${d}</strong><span>${count===6?'✦ ':''}${count}/6</span></button>`}).join('')}</div>`:`<div class="day-strip" aria-label="날짜 선택">${days.map(d=>`<button data-day="${d}" class="${d===routineDay?'active':''}" aria-pressed="${d===routineDay}">${d}</button>`).join('')}</div><div class="daily-grid">${dailyItems.map(([id,label])=>`<div class="daily-item"><span>${esc(label)}</span>${boxes('daily',id,[routineDay])}</div>`).join('')}</div>`}</div><div class="routine-section ${routineTab==='weekly'?'routine-active':''}" data-routine-section="weekly"><div class="routine-section-head"><h2>주간</h2><button class="link" id="copy-routine-items">이전 달 항목 가져오기</button></div>${weeklyItems.map(([id,label])=>`<div class="routine-row"><div>${label?esc(label):customLabel('weekly',id)}</div><div class="week-checks">${(label||s['weekly_'+(id==='custom1'?'1':'2')])?boxes('weekly',id,[1,2,3,4,5]):''}</div></div>`).join('')}</div><div class="routine-section ${routineTab==='monthly'?'routine-active':''}" data-routine-section="monthly"><h2>월간</h2>${monthlyItems.map(([id,label])=>`<div class="routine-row monthly-row"><div>${label?esc(label):customLabel('monthly',id)}</div><div>${(label||s['monthly_'+(id==='custom1'?'1':'2')])?boxes('monthly',id,[1]):''}</div></div>`).join('')}</div><div class="routine-section routine-verse-section ${routineTab==='monthly'?'routine-active':''}" data-routine-section="monthly"><h2>이달의 성구 <button class="link" data-setting="month_verse">${s.month_verse?'수정':'추가'}</button></h2>${s.month_verse?`<p class="month-verse">${esc(s.month_verse)}</p>`:''}</div><p class="routine-status" id="routine-status" role="status"></p></div>`;bindRoutine();requestAnimationFrame(()=>{const strip=document.querySelector('.day-strip'),active=strip?.querySelector('.active');if(strip&&active)strip.scrollLeft=active.offsetLeft-strip.offsetLeft-strip.clientWidth/2+active.clientWidth/2})}
function itemLabel(freq,item){const items=freq==='daily'?dailyItems:freq==='weekly'?weeklyItems:monthlyItems;const s=currentSettings();return items.find(x=>x[0]===item)?.[1]||(freq==='weekly'?s['weekly_'+(item==='custom1'?'1':'2')]:s['monthly_'+(item==='custom1'?'1':'2')])||'직접 정한 항목'}
function openRoutineSetting(field){const s=currentSettings(),isGoal=field==='goal',isVerse=field==='month_verse',labels={goal:'목표 점수',weekly_1:'주간 항목',weekly_2:'주간 항목',monthly_1:'월간 항목',monthly_2:'월간 항목',month_verse:'이달의 성구'};$('#routine-setting-field').value=field;$('#routine-setting-title').textContent=labels[field];$('#routine-setting-label').textContent=labels[field];$('#routine-setting-number').hidden=!isGoal;$('#routine-setting-number').required=isGoal;$('#routine-setting-text').hidden=isGoal;$('#routine-setting-text').required=false;$('#routine-setting-number').value=isGoal?(s.goal??''):'';$('#routine-setting-text').value=!isGoal?(s[field]||''):'';$('#routine-setting-text').rows=isVerse?4:2;$('#routine-setting-message').textContent='';$('#routine-setting-dialog').showModal()}
async function saveRoutineSetting(e){e.preventDefault();const field=$('#routine-setting-field').value,isGoal=field==='goal',value=isGoal?Number($('#routine-setting-number').value):$('#routine-setting-text').value.trim(),btn=e.target.querySelector('button[type=submit]');if(isGoal&&(!Number.isInteger(value)||value<0||value>1000)){$('#routine-setting-message').textContent='0부터 1000까지의 점수를 입력해 주세요.';return}if(!isGoal&&field!=='month_verse'&&value!==currentSettings()[field]){const [freq,num]=field.split('_'),item='custom'+num;const hasChecks=(routineData?.checks||[]).some(x=>x.person===routinePerson&&x.frequency===freq&&x.item===item);if(hasChecks&&!confirm('이미 체크한 항목이에요. 이름을 바꾸고 체크는 그대로 둘까요?'))return}btn.disabled=true;try{await writeRoutine(isGoal?'goal':'setting',isGoal?{value}:{field,value});await readRoutine();$('#routine-setting-dialog').close();if(isGoal)goalVisible=false;routineRender()}catch(err){$('#routine-setting-message').textContent=err.message}finally{btn.disabled=false}}
function setRoutineBusy(busy){routineBusy=busy;document.querySelectorAll('.routine button,.routine input').forEach(el=>el.disabled=busy)}
async function copyRoutineItems(){
 const previous=shiftMonth(routineMonth,-1),fields=['weekly_1','weekly_2','monthly_1','monthly_2'];
 if(!confirm('이전 달에 정한 항목을 가져올까요? 이번 달에 이미 입력한 항목은 그대로 둡니다.'))return;
 setRoutineBusy(true);
 try{
  const result=await rpc('study_routine_read',{p_password:routinePin,p_month:previous});
  if(!result?.ok)throw Error(result?.error||'이전 달을 불러오지 못했습니다.');
  const old=result.settings.find(x=>x.person===routinePerson)||{},current=currentSettings();
  const copy=fields.filter(f=>old[f]&&!current[f]);
  if(!copy.length){$('#routine-status').textContent='가져올 빈 항목이 없습니다.';return}
  for(const field of copy)await writeRoutine('setting',{field,value:old[field]});
  await readRoutine();routineRender();$('#routine-status').textContent=`${copy.length}개 항목을 가져왔습니다.`;
 }catch(err){try{await readRoutine();routineRender()}catch{}$('#routine-status').textContent=err.message}
 finally{setRoutineBusy(false)}
}
function celebrateRoutine(item,allDone){
 const button=document.querySelector(`[data-freq="daily"][data-item="${item}"]`);if(!button)return;
 const card=button.closest('.daily-item');card?.classList.add('just-completed');
 const burst=document.createElement('span');burst.className='check-burst';burst.setAttribute('aria-hidden','true');burst.innerHTML='<i></i><i></i><i></i><i></i><i></i><i></i>';button.appendChild(burst);
 if(allDone){const routine=document.querySelector('.routine'),celebration=document.createElement('div');celebration.className='routine-celebration';celebration.setAttribute('aria-hidden','true');celebration.innerHTML='<div class="celebration-sparkles"><i>✦</i><i>✧</i><i>✦</i><i>✧</i><i>✦</i><i>✧</i></div><div class="celebration-message">오늘의 일과를 모두 마쳤어요 ✨</div>';routine.appendChild(celebration);$('#routine-status').textContent='오늘의 일과를 모두 마쳤어요!';setTimeout(()=>celebration.remove(),3500)}
 setTimeout(()=>{burst.remove();card?.classList.remove('just-completed')},1200);
}
function bindRoutine(){document.querySelectorAll('.daily-item').forEach(card=>card.onclick=e=>{if(!e.target.closest('button'))card.querySelector('button')?.click()});document.querySelectorAll('[data-routine-tab]').forEach(b=>b.onclick=()=>{routineTab=b.dataset.routineTab;routineRender()});$('#routine-view-toggle').onclick=()=>{routineOverview=!routineOverview;routineRender()};$('#copy-routine-items').onclick=copyRoutineItems;document.querySelectorAll('[data-calendar-day]').forEach(b=>b.onclick=()=>{routineDay=Number(b.dataset.calendarDay);routineOverview=false;routineRender()});document.querySelectorAll('[data-routine-person]').forEach(b=>b.onclick=()=>{routinePerson=b.dataset.routinePerson;goalVisible=false;routineRender()});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{routineDay=Number(b.dataset.day);routineRender()});document.querySelectorAll('[data-freq]').forEach(b=>b.onclick=async()=>{if(routineBusy)return;const freq=b.dataset.freq,item=b.dataset.item,pos=Number(b.dataset.pos),willCheck=b.getAttribute('aria-pressed')!=='true',before=freq==='daily'?dailyItems.filter(([id])=>checked('daily',id,pos)).length:0;setRoutineBusy(true);try{await writeRoutine('check',{frequency:freq,item,position:pos,checked:willCheck});await readRoutine();const allDone=freq==='daily'&&willCheck&&before===5&&dailyItems.every(([id])=>checked('daily',id,pos));routineRender();if(freq==='daily'&&willCheck&&checked('daily',item,pos))celebrateRoutine(item,allDone)}catch(err){$('#routine-status').textContent=err.message}finally{setRoutineBusy(false)}});const setMonth=async value=>{if(routineBusy||!/^\d{4}-(0[1-9]|1[0-2])$/.test(value))return;const old=routineMonth,oldDay=routineDay;setRoutineBusy(true);routineMonth=value;let t=todayLocal();routineDay=value===t.month?t.day:1;goalVisible=false;try{await readRoutine();routineRender()}catch(err){routineMonth=old;routineDay=oldDay;$('#routine-status').textContent=err.message;$('#routine-month').value=old}finally{setRoutineBusy(false)}};$('#month-prev').onclick=()=>setMonth(shiftMonth(routineMonth,-1));$('#month-next').onclick=()=>setMonth(shiftMonth(routineMonth,1));$('#routine-month').onchange=e=>setMonth(e.target.value);$('#routine-goal').onclick=()=>{const s=currentSettings();if(s.goal===null||s.goal===undefined)openRoutineSetting('goal');else if(goalVisible){goalVisible=false;routineRender()}else if(confirm('목표를 살짝 볼까요?')){goalVisible=true;routineRender()}};$('#goal-edit')?.addEventListener('click',()=>openRoutineSetting('goal'));document.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>openRoutineSetting(b.dataset.setting))}
let observedDay='';
function refreshCalendar(){const t=todayLocal(),key=t.month+'-'+String(t.day).padStart(2,'0');if(!observedDay){observedDay=key;return}if(key===observedDay)return;const oldMonth=observedDay.slice(0,7),oldDay=Number(observedDay.slice(8));observedDay=key;if((location.hash===''||location.hash==='#/home')&&$('#home-verses'))renderHomeVerses();if(routineMonth===oldMonth){const follow=routineDay===oldDay;if(t.month!==oldMonth){routineMonth=t.month;routineDay=t.day;routineData=null;if(location.hash==='#/routine')routineView()}else if(follow){routineDay=t.day;if(location.hash==='#/routine'&&routineData)routineRender()}}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshCalendar()});setInterval(refreshCalendar,60000);refreshCalendar();
